CREATE TABLE "PushDevice" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "sessionId" UUID NOT NULL, "endpoint" VARCHAR(2048) NOT NULL, "p256dh" VARCHAR(128) NOT NULL, "auth" VARCHAR(64) NOT NULL, "cursor" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "failures" INTEGER NOT NULL DEFAULT 0, "nextAttempt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PushDevice_pkey" PRIMARY KEY ("id"), CONSTRAINT "PushDevice_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PushDevice_endpoint_key" ON "PushDevice"("endpoint");
CREATE INDEX "PushDevice_userId_idx" ON "PushDevice"("userId");
CREATE TABLE "InstallObservation" ("id" UUID NOT NULL, "platform" VARCHAR(12) NOT NULL, "confirmed" BOOLEAN NOT NULL DEFAULT false, "launches" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeen" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InstallObservation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdCampaign" ("id" UUID NOT NULL, "ownerId" UUID NOT NULL, "name" VARCHAR(100) NOT NULL, "body" VARCHAR(280) NOT NULL, "link" VARCHAR(1000), "sourcePostId" UUID, "communityId" UUID, "placement" VARCHAR(12) NOT NULL DEFAULT 'FEED', "budgetKobo" INTEGER NOT NULL, "startAt" TIMESTAMPTZ(3) NOT NULL, "endAt" TIMESTAMPTZ(3) NOT NULL, "status" VARCHAR(12) NOT NULL DEFAULT 'DRAFT', "reviewNote" VARCHAR(500), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "AdCampaign_pkey" PRIMARY KEY ("id"), CONSTRAINT "AdCampaign_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AdCampaign_ownerId_createdAt_idx" ON "AdCampaign"("ownerId","createdAt" DESC);
CREATE INDEX "AdCampaign_status_createdAt_idx" ON "AdCampaign"("status","createdAt" DESC);
INSERT INTO "FeatureSwitch" ("key","enabled") VALUES ('advertising',false) ON CONFLICT ("key") DO NOTHING;
